<script setup lang="ts">import { Link, useForm } from '@inertiajs/vue3'; import MainLayout from '../../Layouts/MainLayout.vue'; defineProps<{students:Array<{id:number;nis:string;nama:string}>}>(); const form=useForm({siswa_id:'',tanggal:new Date().toISOString().slice(0,10),jenis:'masuk',jumlah:'',keterangan:''}); const submit=()=>form.post('/transaksi');</script>
<template><MainLayout><main class="p-6 sm:p-10"><div class="mx-auto max-w-2xl"><Link href="/transaksi" class="text-sm font-semibold text-teal-700">← Kembali ke transaksi</Link><div class="mt-5 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200 sm:p-8"><p class="text-sm font-semibold uppercase tracking-[0.2em] text-teal-700">Operasional</p><h1 class="mt-2 text-3xl font-bold text-slate-950">Transaksi baru</h1><form class="mt-8 space-y-5" @submit.prevent="submit"><div><label class="mb-2 block text-sm font-medium">Siswa</label><select v-model="form.siswa_id" class="w-full rounded-xl border-slate-300 px-4 py-3" required><option value="">Pilih siswa</option><option v-for="s in students" :key="s.id" :value="s.id">{{ s.nis }} · {{ s.nama }}</option></select><p v-if="form.errors.siswa_id" class="mt-2 text-sm text-red-600">{{ form.errors.siswa_id }}</p></div><div class="grid gap-5 sm:grid-cols-2"><div><label class="mb-2 block text-sm font-medium">Tanggal</label><input v-model="form.tanggal" type="date" class="w-full rounded-xl border-slate-300 px-4 py-3" required></div><div><label class="mb-2 block text-sm font-medium">Jenis</label><select v-model="form.jenis" class="w-full rounded-xl border-slate-300 px-4 py-3"><option value="masuk">Setoran</option><option value="keluar">Penarikan</option></select></div></div><div><label class="mb-2 block text-sm font-medium">Jumlah</label><input v-model="form.jumlah" type="number" min="1" step="0.01" class="w-full rounded-xl border-slate-300 px-4 py-3" placeholder="0" required><p v-if="form.errors.jumlah" class="mt-2 text-sm text-red-600">{{ form.errors.jumlah }}</p></div><div><label class="mb-2 block text-sm font-medium">Keterangan <span class="font-normal text-slate-400">(opsional)</span></label><textarea v-model="form.keterangan" rows="3" class="w-full rounded-xl border-slate-300 px-4 py-3"></textarea></div><button :disabled="form.processing" class="w-full rounded-xl bg-teal-800 px-4 py-3 font-semibold text-white disabled:opacity-60">{{ form.processing?'Menyimpan…':'Simpan transaksi' }}</button></form></div></div></main></MainLayout></template>
